			if (fGT_CopyResultToSink.render_func)
				graph.add_library_pass<Passes::FrameGraphTests::FGT_CopyResultToSink>(PassSetupDefault<Passes::FrameGraphTests::FGT_CopyResultToSink>::setup, fGT_CopyResultToSink.render_func, (fGT_CopyResultToSink.flags & ~FrameGraph::PassFlags::Compute));
